
local function getOrCreateFolder(parent, name)
    local f = parent:FindFirstChild(name)
    if not f then
        f = Instance.new("Folder")
        f.Name = name
        f.Parent = parent
    end
    return f
end

local function setScript(parent, name, className, source)
    local s = parent:FindFirstChild(name)
    if not s or s.ClassName ~= className then
        if s then s:Destroy() end
        s = Instance.new(className)
        s.Name = name
        s.Parent = parent
    end
    s.Source = source
    return s
end

setScript(game:GetService("ServerScriptService"), "Bootstrap", "Script", "--!strict\n--[[\n    PANIC SHIFT: Bootstrap.server.lua\n    Master server entry point. Sets up networking remotes, registers services,\n    executes lifecycle phases (Init -> Start), and handles safe shutdown.\n]]\n\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ServerScriptService = game:GetService(\"ServerScriptService\")\n\nlocal Shared = ReplicatedStorage:WaitForChild(\"PanicShiftShared\")\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nprint(\"[PanicShift Server] Starting server initialization...\")\n\n-- 1. Initialize Network Remotes Folder & Remote Instances\nNetwork.InitServer()\nprint(\"[PanicShift Server] Network remotes initialized.\")\n\n-- 2. Service Discovery and Dependency Order\nlocal servicesFolder = script.Parent:WaitForChild(\"Services\")\n\nlocal serviceOrder = {\n    \"DataService\",\n    \"AnalyticsService\",\n    \"EconomyService\",\n    \"InventoryService\",\n    \"ChallengeService\",\n    \"PurchaseService\",\n    \"TaskService\",\n    \"DisasterService\",\n    \"RoundService\",\n}\n\nlocal serviceRegistry: { [string]: any } = {}\n\n-- Load each service module\nfor _, serviceName in ipairs(serviceOrder) do\n    local serviceModule = servicesFolder:FindFirstChild(serviceName)\n    if serviceModule and serviceModule:IsA(\"ModuleScript\") then\n        local success, serviceInstance = pcall(function()\n            return require(serviceModule)\n        end)\n\n        if success and typeof(serviceInstance) == \"table\" then\n            serviceRegistry[serviceName] = serviceInstance\n        else\n            error(string.format(\"[PanicShift Server] Critical failure loading %s: %s\", serviceName, tostring(serviceInstance)))\n        end\n    else\n        error(string.format(\"[PanicShift Server] Service %s not found in Services folder!\", serviceName))\n    end\nend\n\n-- 3. Execute Init Lifecycle\nfor _, serviceName in ipairs(serviceOrder) do\n    local service = serviceRegistry[serviceName]\n    if typeof(service.Init) == \"function\" then\n        service:Init(serviceRegistry)\n    end\nend\nprint(\"[PanicShift Server] All services successfully initialized.\")\n\n-- 4. Execute Start Lifecycle\nfor _, serviceName in ipairs(serviceOrder) do\n    local service = serviceRegistry[serviceName]\n    if typeof(service.Start) == \"function\" then\n        service:Start()\n    end\nend\nprint(\"[PanicShift Server] All services successfully started. Game is LIVE.\")\n\n-- 5. Safe Server Shutdown Hook\ngame:BindToClose(function()\n    print(\"[PanicShift Server] Server shutdown detected. Performing final data persistence...\")\n    if serviceRegistry.RoundService then\n        serviceRegistry.RoundService:CleanupRound()\n    end\n    if serviceRegistry.DataService then\n        serviceRegistry.DataService:SaveAll()\n    end\n    task.wait(2.0)\n    print(\"[PanicShift Server] Final shutdown persistence complete.\")\nend)\n")
setScript(game:GetService("ServerScriptService"), "MapBuilder", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: MapBuilder.lua\n    Procedural & modular builder for the complete PANIC SHIFT supermarket map.\n    Constructs the Lobby, Aisle Gondolas, Checkouts, Stockroom, Maintenance Panels,\n    Overhead Trusses, Lighting, Signage, and Task Anchors.\n]]\n\nlocal Workspace = game:GetService(\"Workspace\")\nlocal CollectionService = game:GetService(\"CollectionService\")\n\nlocal MapBuilder = {}\n\n-- Store Brand Color Palette\nlocal COLORS = {\n    BRAND_GREEN = Color3.fromRGB(26, 120, 68),\n    BRAND_ORANGE = Color3.fromRGB(235, 95, 20),\n    BRAND_YELLOW = Color3.fromRGB(250, 200, 30),\n    FLOOR_LIGHT = Color3.fromRGB(235, 235, 238),\n    FLOOR_DARK = Color3.fromRGB(205, 208, 214),\n    FLOOR_STOCKROOM = Color3.fromRGB(110, 115, 120),\n    FLOOR_LOBBY = Color3.fromRGB(55, 60, 70),\n    WALL_BASE = Color3.fromRGB(240, 240, 245),\n    WALL_ACCENT = Color3.fromRGB(30, 35, 45),\n    METAL_FRAME = Color3.fromRGB(60, 65, 75),\n    SHELF_METAL = Color3.fromRGB(215, 220, 225),\n    SHELF_WOOD = Color3.fromRGB(160, 110, 70),\n    GLASS = Color3.fromRGB(200, 230, 255),\n    NEON_WARM = Color3.fromRGB(255, 250, 240),\n    NEON_RED = Color3.fromRGB(255, 40, 40),\n    CARDBOARD = Color3.fromRGB(195, 155, 105),\n}\n\nlocal function createPart(parent: Instance, name: string, size: Vector3, cframe: CFrame, color: Color3, material: Enum.Material, anchored: boolean?): Part\n    local part = Instance.new(\"Part\")\n    part.Name = name\n    part.Size = size\n    part.CFrame = cframe\n    part.Color = color\n    part.Material = material\n    part.Anchored = if anchored ~= nil then anchored else true\n    part.CanCollide = true\n    part.TopSurface = Enum.SurfaceType.Smooth\n    part.BottomSurface = Enum.SurfaceType.Smooth\n    part.Parent = parent\n    return part\nend\n\nlocal function createSign(parent: Instance, text: string, cframe: CFrame, size: Vector3, bgColor: Color3, textColor: Color3): Part\n    local part = createPart(parent, \"Sign_\" .. text, size, cframe, bgColor, Enum.Material.SmoothPlastic)\n    \n    local surfaceGui = Instance.new(\"SurfaceGui\")\n    surfaceGui.Face = Enum.NormalId.Front\n    surfaceGui.CanvasSize = Vector2.new(400, 150)\n    surfaceGui.Parent = part\n\n    local label = Instance.new(\"TextLabel\")\n    label.Size = UDim2.new(1, 0, 1, 0)\n    label.BackgroundTransparency = 1\n    label.Text = text\n    label.TextColor3 = textColor\n    label.TextScaled = true\n    label.Font = Enum.Font.FredokaOne\n    label.Parent = surfaceGui\n\n    -- Add reverse face sign\n    local backGui = surfaceGui:Clone()\n    backGui.Face = Enum.NormalId.Back\n    backGui.Parent = part\n\n    return part\nend\n\nfunction MapBuilder.Build(): Model\n    -- Remove any old map\n    local existing = Workspace:FindFirstChild(\"SupermarketMap\")\n    if existing then\n        existing:Destroy()\n    end\n\n    local map = Instance.new(\"Model\")\n    map.Name = \"SupermarketMap\"\n    map.Parent = Workspace\n\n    local architectureFolder = Instance.new(\"Folder\")\n    architectureFolder.Name = \"Architecture\"\n    architectureFolder.Parent = map\n\n    local storeFloorFolder = Instance.new(\"Folder\")\n    storeFloorFolder.Name = \"StoreFloor\"\n    storeFloorFolder.Parent = map\n\n    local lobbyFolder = Instance.new(\"Folder\")\n    lobbyFolder.Name = \"Lobby\"\n    lobbyFolder.Parent = map\n\n    local frontEndFolder = Instance.new(\"Folder\")\n    frontEndFolder.Name = \"FrontEnd\"\n    frontEndFolder.Parent = map\n\n    local stockroomFolder = Instance.new(\"Folder\")\n    stockroomFolder.Name = \"Stockroom\"\n    stockroomFolder.Parent = map\n\n    local maintenanceFolder = Instance.new(\"Folder\")\n    maintenanceFolder.Name = \"Maintenance\"\n    maintenanceFolder.Parent = map\n\n    local taskAnchorsFolder = Instance.new(\"Folder\")\n    taskAnchorsFolder.Name = \"TaskAnchors\"\n    taskAnchorsFolder.Parent = map\n\n    print(\"[MapBuilder] Building Supermarket Floors & Foundations...\")\n\n    -- 1. Main Supermarket Floor (150x110 studs)\n    createPart(architectureFolder, \"Floor_MainStore\", Vector3.new(150, 2, 110), CFrame.new(0, -1, 15), COLORS.FLOOR_LIGHT, Enum.Material.Pebble)\n    \n    -- Decorative checkered aisle pattern\n    for x = -60, 60, 30 do\n        createPart(architectureFolder, \"FloorStripe\", Vector3.new(6, 0.1, 100), CFrame.new(x, 0.05, 15), COLORS.FLOOR_DARK, Enum.Material.SmoothPlastic)\n    end\n\n    -- 2. Lobby Floor (90x40 studs)\n    createPart(lobbyFolder, \"Floor_Lobby\", Vector3.new(90, 2, 40), CFrame.new(0, -1, -65), COLORS.FLOOR_LOBBY, Enum.Material.WoodPlanks)\n\n    -- 3. Stockroom Floor (120x30 studs)\n    createPart(stockroomFolder, \"Floor_Stockroom\", Vector3.new(120, 2, 30), CFrame.new(0, -1, 75), COLORS.FLOOR_STOCKROOM, Enum.Material.Concrete)\n\n    -- 4. Perimeter Walls & Ceiling\n    print(\"[MapBuilder] Erecting Walls, Brand Banners & Ceiling...\")\n    local CEILING_Y = 22\n    local WALL_HEIGHT = 22\n\n    -- Left Wall (Main Floor)\n    createPart(architectureFolder, \"Wall_Left\", Vector3.new(2, WALL_HEIGHT, 110), CFrame.new(-75, WALL_HEIGHT / 2, 15), COLORS.WALL_BASE, Enum.Material.Concrete)\n    createPart(architectureFolder, \"Banner_Left\", Vector3.new(0.5, 4, 110), CFrame.new(-73.8, 16, 15), COLORS.BRAND_GREEN, Enum.Material.SmoothPlastic)\n\n    -- Right Wall (Main Floor with coolers)\n    createPart(architectureFolder, \"Wall_Right\", Vector3.new(2, WALL_HEIGHT, 110), CFrame.new(75, WALL_HEIGHT / 2, 15), COLORS.WALL_BASE, Enum.Material.Concrete)\n    createPart(architectureFolder, \"Banner_Right\", Vector3.new(0.5, 4, 110), CFrame.new(73.8, 16, 15), COLORS.BRAND_ORANGE, Enum.Material.SmoothPlastic)\n\n    -- Back Wall (Stockroom Rear)\n    createPart(stockroomFolder, \"Wall_StockroomRear\", Vector3.new(120, WALL_HEIGHT, 2), CFrame.new(0, WALL_HEIGHT / 2, 90), COLORS.FLOOR_STOCKROOM, Enum.Material.Concrete)\n\n    -- Stockroom Partition Wall with Double Door Openings\n    createPart(stockroomFolder, \"Wall_StockPartition_Left\", Vector3.new(50, WALL_HEIGHT, 2), CFrame.new(-35, WALL_HEIGHT / 2, 60), COLORS.WALL_BASE, Enum.Material.Concrete)\n    createPart(stockroomFolder, \"Wall_StockPartition_Right\", Vector3.new(50, WALL_HEIGHT, 2), CFrame.new(35, WALL_HEIGHT / 2, 60), COLORS.WALL_BASE, Enum.Material.Concrete)\n    createPart(stockroomFolder, \"StockDoor_Lintel\", Vector3.new(20, 8, 2), CFrame.new(0, 18, 60), COLORS.WALL_BASE, Enum.Material.Concrete)\n    createSign(stockroomFolder, \"EMPLOYEES ONLY - STOCKROOM\", CFrame.new(0, 13, 58.8), Vector3.new(18, 2.5, 0.5), COLORS.BRAND_ORANGE, Color3.new(1, 1, 1))\n\n    -- Front Glass Facade (between Lobby and Store Floor at Z = -45)\n    createPart(architectureFolder, \"FrontWall_Left\", Vector3.new(30, WALL_HEIGHT, 2), CFrame.new(-45, WALL_HEIGHT / 2, -40), COLORS.WALL_BASE, Enum.Material.Concrete)\n    createPart(architectureFolder, \"FrontWall_Right\", Vector3.new(30, WALL_HEIGHT, 2), CFrame.new(45, WALL_HEIGHT / 2, -40), COLORS.WALL_BASE, Enum.Material.Concrete)\n    createPart(architectureFolder, \"FrontFacadeGlass\", Vector3.new(60, 16, 0.5), CFrame.new(0, 10, -40), COLORS.GLASS, Enum.Material.Glass)\n    createSign(architectureFolder, \"PANIC SHIFT SUPERMARKET\", CFrame.new(0, 19.5, -39.6), Vector3.new(42, 3.5, 0.6), COLORS.BRAND_GREEN, COLORS.BRAND_YELLOW)\n\n    -- Ceiling & Roof\n    createPart(architectureFolder, \"Ceiling_Main\", Vector3.new(150, 1, 110), CFrame.new(0, CEILING_Y, 15), COLORS.METAL_FRAME, Enum.Material.Metal)\n    createPart(stockroomFolder, \"Ceiling_Stockroom\", Vector3.new(120, 1, 30), CFrame.new(0, CEILING_Y, 75), COLORS.FLOOR_STOCKROOM, Enum.Material.Metal)\n    createPart(lobbyFolder, \"Ceiling_Lobby\", Vector3.new(90, 1, 40), CFrame.new(0, CEILING_Y, -65), COLORS.WALL_ACCENT, Enum.Material.SmoothPlastic)\n\n    -- Overhead Industrial Lighting Fixtures\n    print(\"[MapBuilder] Hanging Overhead Fluorescents...\")\n    for x = -45, 45, 30 do\n        for z = -20, 40, 20 do\n            local fixture = createPart(architectureFolder, \"LightFixture\", Vector3.new(12, 0.8, 2), CFrame.new(x, CEILING_Y - 1.5, z), COLORS.METAL_FRAME, Enum.Material.Metal)\n            local tube = createPart(fixture, \"NeonTube\", Vector3.new(11.5, 0.3, 1.2), CFrame.new(x, CEILING_Y - 2, z), COLORS.NEON_WARM, Enum.Material.Neon)\n            \n            local pointLight = Instance.new(\"PointLight\")\n            pointLight.Name = \"FluorescentLight\"\n            pointLight.Brightness = 1.2\n            pointLight.Range = 28\n            pointLight.Color = COLORS.NEON_WARM\n            pointLight.Parent = tube\n        end\n    end\n\n    -- 5. Lobby & 12 Employee Spawn Points (FR-01)\n    print(\"[MapBuilder] Setting up Breakroom Lobby & Safe Spawns...\")\n    createSign(lobbyFolder, \"EMPLOYEE BREAKROOM - GEAR UP FOR SHIFT\", CFrame.new(0, 12, -84), Vector3.new(36, 2.8, 0.4), COLORS.BRAND_GREEN, Color3.new(1, 1, 1))\n\n    -- Breakroom Table & Bench\n    createPart(lobbyFolder, \"BreakroomTable\", Vector3.new(16, 3, 6), CFrame.new(0, 1.5, -60), COLORS.SHELF_WOOD, Enum.Material.Wood)\n    createPart(lobbyFolder, \"TableLeg1\", Vector3.new(1, 3, 1), CFrame.new(-7, 1.5, -60), COLORS.METAL_FRAME, Enum.Material.Metal)\n    createPart(lobbyFolder, \"TableLeg2\", Vector3.new(1, 3, 1), CFrame.new(7, 1.5, -60), COLORS.METAL_FRAME, Enum.Material.Metal)\n\n    -- 12 Spawns (Safe Zone)\n    for i = 1, 12 do\n        local xOffset = -33 + ((i - 1) % 6) * 13\n        local zOffset = (i <= 6) and -76 or -70\n\n        local spawnPart = Instance.new(\"SpawnLocation\")\n        spawnPart.Name = \"LobbySpawn_\" .. i\n        spawnPart.Size = Vector3.new(5, 0.5, 5)\n        spawnPart.CFrame = CFrame.new(xOffset, 0.25, zOffset)\n        spawnPart.Color = (i % 2 == 0) and COLORS.BRAND_GREEN or COLORS.BRAND_ORANGE\n        spawnPart.Material = Enum.Material.SmoothPlastic\n        spawnPart.Anchored = true\n        spawnPart.CanCollide = true\n        spawnPart.Neutral = true\n        spawnPart.Duration = 0\n        spawnPart.Parent = lobbyFolder\n\n        -- Tag as Safe Spawn\n        CollectionService:AddTag(spawnPart, \"SafeSpawn\")\n    end\n\n    -- 6. Grocery Aisles (Gondola Shelving Units)\n    print(\"[MapBuilder] Constructing Aisles 1 to 4...\")\n    local aisleData = {\n        { Number = 1, Name = \"PRODUCE & FRESH BAKERY\", X = -45, Color = COLORS.BRAND_GREEN },\n        { Number = 2, Name = \"CANNED SOUPS & PANTRY\", X = -15, Color = COLORS.BRAND_ORANGE },\n        { Number = 3, Name = \"BREAKFAST CEREALS & SNACKS\", X = 15, Color = COLORS.BRAND_YELLOW },\n        { Number = 4, Name = \"COLD BEVERAGES & DAIRY\", X = 45, Color = Color3.fromRGB(40, 140, 220) },\n    }\n\n    for _, a in ipairs(aisleData) do\n        local aisleModel = Instance.new(\"Model\")\n        aisleModel.Name = \"Aisle_\" .. a.Number\n        aisleModel.Parent = storeFloorFolder\n\n        -- Hanging Aisle Sign\n        createSign(aisleModel, string.format(\"AISLE %d: %s\", a.Number, a.Name), CFrame.new(a.X, 15, 10), Vector3.new(20, 3, 0.5), a.Color, Color3.new(1, 1, 1))\n\n        -- Double-sided Gondola Shelving (Length: 50 studs, Depth: 6 studs, Height: 9 studs)\n        local gondolaBack = createPart(aisleModel, \"GondolaBacking\", Vector3.new(1, 9, 50), CFrame.new(a.X, 4.5, 10), COLORS.SHELF_METAL, Enum.Material.Metal)\n        \n        -- Shelves (3 tiers on each side)\n        for tier = 1, 3 do\n            local shelfY = tier * 2.8\n            -- Left side shelf\n            local shelfLeft = createPart(aisleModel, \"Shelf_L_Tier\" .. tier, Vector3.new(2.5, 0.4, 48), CFrame.new(a.X - 1.5, shelfY, 10), COLORS.SHELF_METAL, Enum.Material.Metal)\n            -- Right side shelf\n            local shelfRight = createPart(aisleModel, \"Shelf_R_Tier\" .. tier, Vector3.new(2.5, 0.4, 48), CFrame.new(a.X + 1.5, shelfY, 10), COLORS.SHELF_METAL, Enum.Material.Metal)\n\n            -- Product boxes / cans on shelves\n            for z = -12, 32, 8 do\n                local prodLeft = createPart(aisleModel, \"Product_L_\" .. tier .. \"_\" .. z, Vector3.new(1.8, 1.6, 2.2), CFrame.new(a.X - 1.5, shelfY + 1.0, z), a.Color, Enum.Material.SmoothPlastic)\n                local prodRight = createPart(aisleModel, \"Product_R_\" .. tier .. \"_\" .. z, Vector3.new(1.8, 1.6, 2.2), CFrame.new(a.X + 1.5, shelfY + 1.0, z), COLORS.CARDBOARD, Enum.Material.SmoothPlastic)\n            end\n        end\n\n        -- Decorative Endcaps at both ends of each aisle\n        for _, endZ in ipairs({ -15, 35 }) do\n            local endcap = createPart(aisleModel, \"Endcap_Display\", Vector3.new(7, 8, 2), CFrame.new(a.X, 4, endZ), a.Color, Enum.Material.SmoothPlastic)\n            createSign(endcap, \"SPECIAL SALE!\", CFrame.new(a.X, 7.5, endZ + ((endZ < 0) and -1.1 or 1.1)), Vector3.new(5.5, 1.4, 0.2), COLORS.BRAND_YELLOW, Color3.new(0, 0, 0))\n        end\n\n        -- Tag Aisle 2 for Product Avalanche disaster (FR-10 / Milestone 4)\n        if a.Number == 2 then\n            CollectionService:AddTag(aisleModel, \"AvalancheAisle\")\n        end\n    end\n\n    -- 7. Checkouts & Front End (Registers 1 to 4)\n    print(\"[MapBuilder] Assembling Checkout Lanes & Conveyors...\")\n    for reg = 1, 4 do\n        local regX = -45 + (reg - 1) * 30\n        local regZ = -30\n\n        local checkoutModel = Instance.new(\"Model\")\n        checkoutModel.Name = \"Register_\" .. reg\n        checkoutModel.Parent = frontEndFolder\n\n        -- Counter base\n        createPart(checkoutModel, \"CounterBase\", Vector3.new(6, 3.2, 14), CFrame.new(regX, 1.6, regZ), COLORS.SHELF_METAL, Enum.Material.Metal)\n        -- Black conveyor belt\n        createPart(checkoutModel, \"ConveyorBelt\", Vector3.new(3, 0.2, 12), CFrame.new(regX - 1, 3.3, regZ), Color3.fromRGB(30, 30, 35), Enum.Material.Fabric)\n        -- Scanner glass\n        createPart(checkoutModel, \"ScannerGlass\", Vector3.new(2, 0.1, 2), CFrame.new(regX - 1, 3.45, regZ + 2), COLORS.NEON_RED, Enum.Material.Neon)\n        -- Monitor stand\n        createPart(checkoutModel, \"MonitorPole\", Vector3.new(0.4, 2.5, 0.4), CFrame.new(regX + 2, 4.2, regZ), COLORS.METAL_FRAME, Enum.Material.Metal)\n        local monitor = createPart(checkoutModel, \"RegisterScreen\", Vector3.new(2.5, 1.8, 0.4), CFrame.new(regX + 2, 5.2, regZ), Color3.fromRGB(20, 20, 25), Enum.Material.SmoothPlastic)\n        createSign(monitor, \"LANE \" .. reg, CFrame.new(regX + 2, 5.2, regZ - 0.25), Vector3.new(2.4, 1.6, 0.1), COLORS.BRAND_GREEN, Color3.new(1, 1, 1))\n\n        -- Order Delivery Target Anchor\n        local dropTarget = createPart(taskAnchorsFolder, \"OrderDropTarget_\" .. reg, Vector3.new(3, 0.5, 3), CFrame.new(regX - 1, 3.5, regZ - 3), COLORS.BRAND_YELLOW, Enum.Material.Neon)\n        dropTarget.Transparency = 0.5\n        CollectionService:AddTag(dropTarget, \"OrderDropTarget\")\n        CollectionService:AddTag(dropTarget, \"TaskAnchor\")\n    end\n\n    -- Cart Corrals (Left and Right front entrance)\n    print(\"[MapBuilder] Installing Shopping Cart Return Corrals...\")\n    for _, cx in ipairs({ -65, 65 }) do\n        local corral = Instance.new(\"Model\")\n        corral.Name = \"CartCorral_\" .. ((cx < 0) and \"Left\" or \"Right\")\n        corral.Parent = frontEndFolder\n\n        createPart(corral, \"Rail_L\", Vector3.new(0.6, 3, 16), CFrame.new(cx - 3, 1.5, -30), COLORS.METAL_FRAME, Enum.Material.Metal)\n        createPart(corral, \"Rail_R\", Vector3.new(0.6, 3, 16), CFrame.new(cx + 3, 1.5, -30), COLORS.METAL_FRAME, Enum.Material.Metal)\n        createPart(corral, \"Rail_Back\", Vector3.new(6, 3, 0.6), CFrame.new(cx, 1.5, -22), COLORS.METAL_FRAME, Enum.Material.Metal)\n        createSign(corral, \"CART RETURN\", CFrame.new(cx, 4.5, -30), Vector3.new(7, 1.8, 0.3), COLORS.BRAND_ORANGE, Color3.new(1, 1, 1))\n        \n        local cartZone = createPart(corral, \"CartDepositZone\", Vector3.new(5.5, 0.2, 14), CFrame.new(cx, 0.1, -30), COLORS.BRAND_YELLOW, Enum.Material.Neon)\n        cartZone.Transparency = 0.6\n        CollectionService:AddTag(cartZone, \"CartCorral\")\n    end\n\n    -- 8. Back Stockroom Pallets & Box Racks\n    print(\"[MapBuilder] Stocking Warehouse Pallets & Boxes...\")\n    for i = 1, 3 do\n        local px = -35 + (i - 1) * 35\n        local pz = 75\n\n        -- Wooden pallet\n        local pallet = createPart(stockroomFolder, \"Pallet_\" .. i, Vector3.new(8, 0.8, 8), CFrame.new(px, 0.4, pz), COLORS.SHELF_WOOD, Enum.Material.WoodPlanks)\n        \n        -- Stacked Cardboard boxes\n        for bx = -2, 2, 2 do\n            for bz = -2, 2, 2 do\n                local box = createPart(stockroomFolder, \"StockBox_\" .. i .. \"_\" .. bx .. \"_\" .. bz, Vector3.new(1.8, 1.8, 1.8), CFrame.new(px + bx, 1.7, pz + bz), COLORS.CARDBOARD, Enum.Material.SmoothPlastic)\n                CollectionService:AddTag(box, \"StockBox\")\n            end\n        end\n\n        -- Restock Source Anchor\n        local restockSource = createPart(taskAnchorsFolder, \"RestockSource_\" .. i, Vector3.new(7, 0.4, 7), CFrame.new(px, 0.3, pz), COLORS.BRAND_GREEN, Enum.Material.Neon)\n        restockSource.Transparency = 0.6\n        CollectionService:AddTag(restockSource, \"RestockSource\")\n        CollectionService:AddTag(restockSource, \"TaskAnchor\")\n    end\n\n    -- 9. Maintenance & Repair Stations (FR-07 / FR-08)\n    print(\"[MapBuilder] Mounting Electrical Breakers & Coolers...\")\n\n    -- Breaker Box 1 (Store Left Wall)\n    local breaker1 = createPart(maintenanceFolder, \"BreakerPanel_1\", Vector3.new(0.6, 4, 3), CFrame.new(-74.5, 5, 20), Color3.fromRGB(45, 45, 50), Enum.Material.Metal)\n    createSign(breaker1, \"MAIN BREAKER 1\", CFrame.new(-74.1, 6.2, 20), Vector3.new(2.8, 0.8, 0.2), COLORS.BRAND_ORANGE, Color3.new(1, 1, 1))\n    CollectionService:AddTag(breaker1, \"RepairTarget\")\n    CollectionService:AddTag(breaker1, \"TaskAnchor\")\n\n    -- Breaker Box 2 (Stockroom Rear Wall)\n    local breaker2 = createPart(maintenanceFolder, \"BreakerPanel_2\", Vector3.new(3, 4, 0.6), CFrame.new(35, 5, 89.5), Color3.fromRGB(45, 45, 50), Enum.Material.Metal)\n    createSign(breaker2, \"AUX BREAKER 2\", CFrame.new(35, 6.2, 89.1), Vector3.new(2.8, 0.8, 0.2), COLORS.BRAND_ORANGE, Color3.new(1, 1, 1))\n    CollectionService:AddTag(breaker2, \"RepairTarget\")\n    CollectionService:AddTag(breaker2, \"TaskAnchor\")\n\n    -- Refrigerated Dairy Coolers (Along Right Wall)\n    for c = 1, 4 do\n        local cz = -10 + (c - 1) * 16\n        local cooler = createPart(maintenanceFolder, \"CoolerUnit_\" .. c, Vector3.new(4, 9, 14), CFrame.new(72.5, 4.5, cz), COLORS.SHELF_METAL, Enum.Material.Metal)\n        createPart(cooler, \"CoolerGlassDoor\", Vector3.new(0.3, 8.2, 13.2), CFrame.new(70.3, 4.5, cz), COLORS.GLASS, Enum.Material.Glass)\n        createSign(cooler, \"38°F DAIRY COOLER\", CFrame.new(70.1, 8.2, cz), Vector3.new(7, 1.2, 0.1), Color3.fromRGB(20, 80, 160), Color3.new(1, 1, 1))\n        \n        -- One cooler is prone to breakdown (Repair Task)\n        if c == 2 then\n            CollectionService:AddTag(cooler, \"RepairTarget\")\n            CollectionService:AddTag(cooler, \"TaskAnchor\")\n        end\n    end\n\n    -- Mop Cleaning Stations (Cleaning task anchors)\n    for _, mopPos in ipairs({ Vector3.new(-70, 0.2, -35), Vector3.new(50, 0.2, 70) }) do\n        local mopStation = createPart(maintenanceFolder, \"MopStation\", Vector3.new(4, 0.4, 4), CFrame.new(mopPos), COLORS.BRAND_YELLOW, Enum.Material.SmoothPlastic)\n        createSign(mopStation, \"MOP & BUCKET\", CFrame.new(mopPos + Vector3.new(0, 3, 0)), Vector3.new(3.5, 1, 0.2), COLORS.BRAND_YELLOW, Color3.new(0, 0, 0))\n        CollectionService:AddTag(mopStation, \"MopPickup\")\n        CollectionService:AddTag(mopStation, \"TaskAnchor\")\n    end\n\n    -- Spill Target Anchors (Designated locations where chemical/juice spills appear)\n    local spillLocations = {\n        Vector3.new(-45, 0.1, 15),  -- Aisle 1\n        Vector3.new(-15, 0.1, 0),   -- Aisle 2\n        Vector3.new(15, 0.1, 25),   -- Aisle 3\n        Vector3.new(45, 0.1, -5),   -- Aisle 4\n        Vector3.new(-10, 0.1, -25), -- Near Checkout 2\n        Vector3.new(20, 0.1, -25),  -- Near Checkout 3\n    }\n    for idx, sPos in ipairs(spillLocations) do\n        local anchor = createPart(taskAnchorsFolder, \"SpillAnchor_\" .. idx, Vector3.new(4, 0.1, 4), CFrame.new(sPos), Color3.fromRGB(255, 100, 200), Enum.Material.SmoothPlastic)\n        anchor.Transparency = 1 -- Invisible trigger anchor\n        CollectionService:AddTag(anchor, \"SpillAnchor\")\n        CollectionService:AddTag(anchor, \"TaskAnchor\")\n    end\n\n    -- Shelf Restock Target Anchors (empty shelf sections needing boxes)\n    local restockTargets = {\n        Vector3.new(-43, 3.5, 10),\n        Vector3.new(-13, 6.2, 20),\n        Vector3.new(17, 3.5, -5),\n        Vector3.new(47, 6.2, 15),\n    }\n    for idx, rPos in ipairs(restockTargets) do\n        local anchor = createPart(taskAnchorsFolder, \"RestockTarget_\" .. idx, Vector3.new(3, 2, 3), CFrame.new(rPos), COLORS.BRAND_YELLOW, Enum.Material.Neon)\n        anchor.Transparency = 0.7\n        CollectionService:AddTag(anchor, \"RestockTarget\")\n        CollectionService:AddTag(anchor, \"TaskAnchor\")\n    end\n\n    print(string.format(\"[MapBuilder] Build complete! Generated %d total instances in Workspace.SupermarketMap.\", #map:GetDescendants()))\n    return map\nend\n\nreturn MapBuilder\n")
setScript(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "ClientBootstrap", "LocalScript", "--!strict\n--[[\n    PANIC SHIFT: ClientBootstrap.client.lua\n    Master client entry point. Waits for network remotes, loads controllers,\n    and manages client startup lifecycle.\n]]\n\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nprint(\"[PanicShift Client] Starting client initialization...\")\n\n-- 1. Ensure shared components and network replication\nlocal Shared = ReplicatedStorage:WaitForChild(\"PanicShiftShared\", 15) :: Folder\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\n-- 2. Discover and register controllers\nlocal controllersFolder = script.Parent:WaitForChild(\"Controllers\")\n\nlocal controllerOrder = {\n    \"EffectsController\",\n    \"CameraController\",\n    \"InteractionController\",\n    \"InputController\",\n    \"UIController\",\n}\n\nlocal controllerRegistry: { [string]: any } = {}\n\nfor _, controllerName in ipairs(controllerOrder) do\n    local mod = controllersFolder:FindFirstChild(controllerName)\n    if mod and mod:IsA(\"ModuleScript\") then\n        local success, controllerInstance = pcall(function()\n            return require(mod)\n        end)\n        if success and typeof(controllerInstance) == \"table\" then\n            controllerRegistry[controllerName] = controllerInstance\n        else\n            error(string.format(\"[PanicShift Client] Error loading %s: %s\", controllerName, tostring(controllerInstance)))\n        end\n    else\n        error(string.format(\"[PanicShift Client] Controller %s missing from Controllers folder!\", controllerName))\n    end\nend\n\n-- 3. Execute Init Lifecycle\nfor _, controllerName in ipairs(controllerOrder) do\n    local ctrl = controllerRegistry[controllerName]\n    if typeof(ctrl.Init) == \"function\" then\n        ctrl:Init(controllerRegistry)\n    end\nend\nprint(\"[PanicShift Client] All client controllers initialized.\")\n\n-- 4. Execute Start Lifecycle\nfor _, controllerName in ipairs(controllerOrder) do\n    local ctrl = controllerRegistry[controllerName]\n    if typeof(ctrl.Start) == \"function\" then\n        ctrl:Start()\n    end\nend\nprint(\"[PanicShift Client] Client controllers started. Ready to work the shift!\")\n")
